import {createBulkWorkflow,FLOW_DEMOS} from './flow-controller.js?v=11';
import {ACTIVE_STATUSES,STATUS_LABELS,filterPlans,groupPlans,validRange} from './list-model.js?v=11';
import {LIMIT,PAGE_SIZE,TEMPLATE,elements,plans,reasonLabels,availableOps,dateFor,validate,classify as classifyModel,totals,initialConfig,execute,STAGES,stageDates,stageForElement,initialAddConfig,validateAdd,addRows} from './model.js?v=11';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const image=(n,alt='',cls='')=>`<img class="${cls}" src="assets/${n}" alt="${alt}">`,chev=()=>image('chevron-down-outlined.svg'),cross=()=>image('cross-outlined.svg');
let state={page:1,selected:new Set(),group:'none',groupOpen:{},groupPages:{},statuses:[],startFrom:'',startTo:'',finishFrom:'',finishTo:'',mode:'edit',addStage:null,addConfig:initialAddConfig(),open:true,filters:true,query:'',tab:'assigned',screen:null,element:null,config:initialConfig(),elementQuery:'',type:'Все типы',catalogQuery:'',pendingCourse:null,excluded:new Set(),special:'',preview:[],result:null,error:'',demoOpen:false,partial:false,applied:new Map(),hasAccess:true};

function classify(ids,el,c,excluded=new Set(),special=''){return classifyModel(ids,el,c,excluded,special).map(r=>{const saved=state.applied.get(`${r.plan.id}/${el.id}/${c.op}`);if(c.op==='replace'&&saved===c.replacement?.id&&r.status==='change')return {...r,status:'same'};if(c.op==='replace'&&r.status==='change'&&r.plan.existingMaterials.includes(c.replacement?.id)&&c.duplicateDecision!=='allow')return {...r,status:'skip',reason:'duplicate'};return r;});}
let pendingReset=null,lastFocus=null,loadingTimer=null;
const chosen=()=>[...state.selected],selectedElement=()=>elements.find(e=>e.id===state.element),selectionCount=()=>state.selected.size;
const filtered=()=>filterPlans(plans,state);
const currentRows=()=>state.group==='none'?filtered().slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE):listGroups().filter((g,i)=>groupExpanded(g,i)).flatMap(g=>groupPageRows(g)),selectableRows=()=>currentRows().filter(p=>p.reason!=='closed');
const formatDate=d=>d==='Без срока'?d:new Date(d+'T12:00:00Z').toLocaleDateString('ru-RU');
const check=(id,checked,label,disabled=false)=>`<input type="checkbox" ${id?`data-row="${id}"`:''} ${checked?'checked':''} ${disabled?'disabled':''} aria-label="${esc(label)}">`;
const action=(id,label,cls='btn',disabled=false)=>`<button class="${cls}" data-action="${id}" ${disabled?'disabled':''} ${id==='clear'?'aria-label="Снять выбор"':''} ${['bulk-elements','edit-elements','add-elements','edit-properties','delete-elements'].includes(id)?'data-tip="Перед изменением элементов сгруппируйте планы «По шаблону» и выберите активные планы в фильтре «Статус». Так проще выбрать нужные элементы." aria-describedby="bulk-tip"':''}>${label}</button>`;
const empty=(title,subtitle='',retry='')=>`<div class="empty"><h3>${title}</h3>${subtitle?`<p>${subtitle}</p>`:''}${retry?action(retry,'Повторить','btn'):''}</div>`;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500);}
function focusInput(id,pos){const e=document.getElementById(id);e?.focus();if(e?.setSelectionRange&&typeof pos==='number')e.setSelectionRange(pos,pos);}
function redrawInput(id,pos,fn){fn();focusInput(id,pos);}
function shell(){const list=currentRows(),n=selectionCount(),total=filtered().length;$('#page').classList.toggle('has-selection',!!n);$('#page').classList.toggle('is-grouped',state.group!=='none');$('#page').innerHTML=`
 <div class="heading"><h1>Планы сотрудников</h1><div class="heading-actions">${action('reports',image('6264-553229-imgIcon.svg')+'Отчёты','btn ghost')}${action('create',image('6264-553229-imgPlusOutlined.svg')+'Создать','btn primary')}</div></div>
 <nav class="tabs" aria-label="Планы сотрудников"><button data-action="tab-assigned" aria-current="${state.tab==='assigned'?'page':'false'}">Назначенные <span>240</span></button><button data-action="tab-drafts" aria-current="${state.tab==='drafts'?'page':'false'}">Черновики <span>5</span></button></nav>
 ${state.tab==='drafts'?empty('Черновики планов','Массовое изменение элементов доступно во вкладке «Назначенные».'):stats()+`
 <div class="toolbar"><label class="search">${image('magnifier-outlined.svg')}<input id="table-search" value="${esc(state.query)}" placeholder="Поиск" aria-label="Поиск планов"></label>${action('filters',image('adjustments-outlined.svg')+'Фильтры','btn '+(state.filters?'active':''))}<span class="spacer"></span>${action('columns',image('columns.svg')+'Столбцы')}${action('group',image('6264-553231-imgColor3.svg')+groupName())}</div>
 ${state.filters?`<div class="filter-panel">${filterChip('status','Статус',statusCaption())}${filterChip('start','Дата начала',rangeCaption(state.startFrom,state.startTo))}${filterChip('finish','Дата окончания',rangeCaption(state.finishFrom,state.finishTo))}${action('add-filter','+ Фильтр','text-btn muted')}</div>`:''}
 ${preparationNote()}
 ${(state.result||state.addResult||state.workflowSummary)?`<div class="result-link"><strong>${state.workflowSummary||resultHeadline()}</strong><span class="spacer"></span>${action('open-result','Посмотреть результат','text-btn')}</div>`:''}
 ${n?`<div class="selection-note"><span>Выбрано ${n} ${n===1?'план':'планов'} на этом экране.</span><span class="muted">Всего по фильтру: ${total}</span><span class="spacer"></span>${action('clear','Снять выбор','text-btn')}</div>`:''}
 <div class="table-scroll"><table><colgroup><col style="width:336px"><col style="width:296px"><col style="width:256px"><col style="width:296px"><col style="width:191px"><col style="width:200px"><col style="width:280px"><col style="width:160px"><col style="width:160px"><col style="width:280px"></colgroup><thead><tr><th><label class="row">${check('',selectableRows().length>0&&selectableRows().every(p=>state.selected.has(p.id)),'Выбрать планы на текущей странице')}<span>Сотрудник ${image('arrow-up-down-outlined.svg')}</span></label></th>${['Департамент','Категория плана','Название плана','Статус','Прогресс','Руководитель','Дата начала','Дата окончания','Помощники'].map(t=>`<th>${t} ${image('arrow-up-down-outlined.svg')}</th>`).join('')}</tr></thead><tbody>
 ${tableBody()}</tbody></table>${!total?empty('Планы не найдены','Попробуйте изменить поиск или фильтры'):''}</div>
 ${paginationView(total)}`}`;
 bindPreparationTips();const headerCheck=$('thead input');if(headerCheck)headerCheck.disabled=selectableRows().length===0;if(headerCheck)headerCheck.indeterminate=n>0&&!selectableRows().every(p=>state.selected.has(p.id));
 $('#bulk-root').innerHTML=n&&state.tab==='assigned'?`<div class="bulk"><strong>Выбрано: ${n}</strong><div class="bulk-actions">${action('bulk-elements','Элементы '+chev(),'btn new-action',!state.hasAccess)}${action('bulk-participants','Участники '+chev(),'btn')}${action('bulk-plan','План '+chev(),'btn')}</div>${action('clear',cross(),'icon-btn')}</div>`:'';
}
function groupName(){return {template:'По шаблону',none:'Без группировки',department:'По департаменту',leader:'По руководителю',position:'По должности',kind:'По категории',status:'По статусу'}[state.group];}
function groupLabel(){return state.group==='template'?`Шаблон «${TEMPLATE}»`:state.group==='kind'?'Категория «Адаптация»':groupName();}
function stats(){const icons=['imgColor','imgColor1','imgColor2','imgColor3','imgColor4','imgColor5'];return `<div class="widgets">${[['Активные',230,'#edf6ff'],['С риском',24,'#fef2ef'],['Без целей',12,'#fff3e6'],['Просрочка КТ',8,'#fff1f3'],['Ждут ревью',6,'#fdf4d7'],['Завершаются',18,'#e8f9ec']].map(([t,n,c],i)=>`<div class="widget"><span class="widget-icon" style="background:${c}"><span class="widget-glyph" style="mask-image:url('assets/6264-553230-${icons[i]}.svg')"></span></span><div><span class="muted">${t}</span><strong>${n}</strong></div></div>`).join('')}</div>`;}
function openScreen(name){lastFocus=document.activeElement;state.screen=name;state.error='';drawModal();}
function closeScreen(){if(['running','add-running'].includes(state.screen))return;state.screen=null;$('#modal-root').innerHTML='';$('#popover-root').innerHTML='';lastFocus?.focus?.();}
function heading(){return ['review','preview-loading','preview-error'].includes(state.screen)?'Проверьте изменения':state.screen==='catalog'?'Выберите '+({Курс:'курс',Статья:'статью',Файл:'файл',Опрос:'опрос'}[selectedElement()?.type]||'материал'):state.screen==='result'?'Результат изменения':state.screen==='running'?'Изменяем элементы':'Изменить элементы';}
function steps(){const at=state.screen==='element'?1:state.screen==='change'||state.screen==='catalog'?2:3;return `<div class="steps">${['Элемент','Изменение','Проверка'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${i+1===at?'current':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;}
function drawModal(){if(state.screen?.startsWith('add-')){drawAddModal();return;}if(!state.screen){$('#modal-root').innerHTML='';return;}if(state.screen==='reset'){drawReset();return;}let body='',footer='',description='',wide=false;const el=selectedElement();
 if(state.screen==='element'){description='Выберите элемент, который нужно изменить в выбранных планах';body=elementStep();footer=action('cancel','Отменить','btn ghost')+action('element-next','Далее','btn primary',!el||!!el.unavailable||state.special==='element-error'||state.special==='no-elements'||state.special==='element-loading');}
 if(state.screen==='change'){body=changeStep();footer=action('element-back','Назад','btn ghost left')+action('check','Проверить изменения','btn primary',!!validate(state.config,el));}
 if(state.screen==='catalog'){description='Материал того же типа. Выберите один вариант';body=catalogStep();footer=action('catalog-cancel','Назад','btn ghost left')+action('catalog-choose','Выбрать','btn primary',!state.pendingCourse);}
 if(state.screen==='review'){wide=true;description=`Выбрано планов: ${selectionCount()}. Изменения ещё не применены`;body=reviewStep();const count=totals(state.preview).change,pending=replacementDuplicateCount()>0&&!state.config.duplicateDecision;footer=action('change-back','Назад','btn ghost left')+action('apply',applyLabel(count),'btn primary',count===0||pending);}
 if(['element-loading','preview-loading'].includes(state.screen)){body=`<div class="empty"><span class="loader"></span><h3>Проверяем изменения…</h3><p>Ничего не сохраняем</p></div>`;footer=action('change-back','Назад','btn ghost');}
 if(state.screen==='preview-error'){body=empty('Не удалось проверить изменения','Настройки сохранены. Попробуйте ещё раз.','check-retry');footer=action('change-back','Назад','btn ghost');}
 if(state.screen==='running'){body=`<div class="empty"><span class="loader"></span><h3>${state.config.op==='replace'?'Заменяем материал':'Изменяем элементы'} в ${totals(state.preview).change} планах…</h3><p>Дождитесь результата</p></div>`;footer=action('none','Выполняем…','btn primary',true);}
 if(state.screen==='result'){wide=true;body=resultStep();footer=state.result?.some(r=>r.result==='error')?action('retry-errors',`Повторить для ${state.result.filter(r=>r.result==='error').length} планов с ошибкой`,'btn')+action('done','Готово','btn primary'):action('done','Готово','btn primary');}
 if(state.screen==='limit'){body=`<div class="notice error">Можно выбрать не более ${LIMIT} планов за одну операцию.</div><p class="scope-note">Выберите планы на текущей странице. Выбор всех результатов фильтра недоступен.</p>`;footer=action('cancel','Понятно','btn primary');}
 if(state.screen==='denied'){body=empty('Недостаточно прав','Массовое изменение доступно с правом редактирования назначенных планов.');footer=action('cancel','Закрыть','btn');}
 $('#modal-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${heading()}</h2>${state.screen!=='running'?`<button class="icon-btn" data-action="cancel" aria-label="Закрыть">${cross()}</button>`:''}${description?`<p>${description}</p>`:''}${['element','change','review'].includes(state.screen)?steps():''}</header><div class="modal-content">${body}${state.error?`<div class="error-text" role="alert">${esc(state.error)}</div>`:''}</div><footer class="modal-foot">${footer}</footer></section></div>`;
 $('#modal-root .modal-head button')?.focus();
}
function elementStep(){if(state.special==='element-loading')return `<div class="empty"><span class="loader"></span><h3>Загружаем элементы…</h3></div>`;if(state.special==='element-error')return empty('Не удалось загрузить элементы','Попробуйте ещё раз. Выбранные планы сохранены.','elements-retry');if(state.special==='no-elements')return empty('В выбранных планах нет элементов');const count=selectionCount();let list=elements.filter(e=>(state.type==='Все типы'||e.type===state.type)&&e.name.toLowerCase().includes(state.elementQuery.toLowerCase()));if(state.special==='unavailable')list=list.filter(e=>e.unavailable);
 return `<p class="context-note">Выбрано планов: ${count}</p>${preparationNote(true)}<div class="element-search"><label class="search">${image('magnifier-outlined.svg')}<input id="element-search" placeholder="Поиск по названию элемента" aria-label="Поиск элементов" value="${esc(state.elementQuery)}"></label><select class="select" id="element-type" aria-label="Тип элемента">${['Все типы','Курс','Статья','Задача','Файл','Опрос'].map(t=>`<option ${t===state.type?'selected':''}>${t}</option>`).join('')}</select></div><div class="element-list">${list.length?list.map(e=>{const rows=classify(chosen(),e,{...initialConfig(),replacement:{id:900}});const t=totals(rows),found=rows.filter(r=>!['missing','ambiguous'].includes(r.reason)).length;return `<label class="element-option"><input type="radio" name="element" value="${e.id}" ${state.element===e.id?'checked':''} ${e.unavailable?'disabled':''}><span class="element-icon">${image(e.type==='Задача'?'check-outlined.svg':'book-outlined.svg')}</span><span class="body"><strong>${e.type} · ${e.name}</strong><span class="meta">${plans.find(p=>p.templateId===stageForElement(e).templateId).template}</span>${elementTiming(e)}<span class="availability">Найден в ${found} планах · доступны для изменения ${t.change}${e.unavailable?' · все элементы выполнены':''}</span></span></label>`;}).join(''):empty('Элементы не найдены','Попробуйте другой запрос или тип элемента')}</div>`;
}
function elementContext(){const e=selectedElement();return `<div class="chosen-element"><div class="element-icon">${image(e.type==='Задача'?'check-outlined.svg':'book-outlined.svg')}</div><div class="body"><strong>${e.type} «${e.name}»</strong><p class="muted">${TEMPLATE}</p>${elementTiming(e)}</div>${action('element-back','Другой элемент','text-btn')}</div>`;}
const opNames={replace:'Заменить материал',required:'Изменить обязательность',deadline:'Изменить срок элемента',task:'Изменить задачу'};
function changeStep(){const c=state.config,e=selectedElement();let html=elementContext()+`<div class="form-field"><span class="field-label">Что изменить</span><select class="select" id="operation" aria-label="Что изменить">${availableOps(e).map(op=>`<option value="${op}" ${c.op===op?'selected':''}>${opNames[op]}</option>`).join('')}</select></div><div class="form-field">`;
 if(c.op==='replace')html+=`<div class="comparison"><div><span class="muted">Текущий материал</span><strong>${e.type} «${e.name}»</strong></div><div><span class="muted">Новый материал</span>${c.replacement?`<strong>${e.type} «${c.replacement.name}»</strong>`:''}${action('catalog',c.replacement?'Выбрать другой':'Выберите '+({Курс:'курс',Статья:'статью',Файл:'файл',Опрос:'опрос'}[e.type]),'btn')}</div></div><p class="hint" style="margin-top:12px">Этап, порядок, обязательность и сроки элемента сохранятся. Исходный материал не изменится.</p><div class="notice" style="margin-top:16px">Начатые и выполненные элементы будут пропущены. Результаты сотрудников не сбрасываются.</div>`;
 if(c.op==='required')html+=`<p class="hint" style="margin-bottom:12px">В выбранных планах обязательность различается.</p>${[true,false].map(v=>`<label class="radio-line"><input type="radio" name="required" value="${v}" ${c.required===v?'checked':''}>${v?'Обязательный':'Необязательный'}</label>`).join('')}<div class="notice warning" style="margin-top:16px">Обязательность влияет на условия завершения плана. Материал, положение в маршруте и результаты выполнения сохранятся.</div>`;
 if(c.op==='deadline')html+=`<span class="field-label">Новый срок элемента</span>${[['date','Конкретная дата'],['days','Количество дней от начала плана'],['none','Без срока']].map(([v,t])=>`<label class="radio-line"><input type="radio" name="date-mode" value="${v}" ${c.dateMode===v?'checked':''}>${t}</label>`).join('')}<div style="margin:12px 0 0 28px">${c.dateMode==='date'?`<input class="text-field" type="date" id="element-date" aria-label="Новый срок элемента" value="${c.date}">`:c.dateMode==='days'?`<label class="row">Выполнить в течение <input class="text-field" style="width:90px" type="number" min="0" id="days" value="${c.days}" aria-label="Количество дней"> дней от начала плана</label>`:''}</div><p class="hint" style="margin-top:16px">Срок проверяется для каждого плана. Окончание этапа и всего плана не переносится.</p>${c.dateMode==='date'&&c.date<'2026-10-23'?'<div class="notice warning" style="margin-top:12px">После изменения элемент будет просрочен.</div>':''}`;
 if(c.op==='task')html+=`<p class="hint" style="margin-bottom:16px">В выбранных планах есть разные варианты задачи. Проверьте текущие значения перед заменой.</p><label class="check-label">${check('',c.changeName,'Изменить название')}<span>Изменить название</span></label>${c.changeName?`<input class="text-field" id="task-title" aria-label="Название задачи" value="${esc(c.title)}" style="margin-top:8px">`:''}<label class="check-label" style="margin-top:16px">${check('',c.changeDescription,'Изменить описание')}<span>Изменить описание</span></label>${c.changeDescription?`<textarea id="task-description" aria-label="Описание задачи" rows="4" style="margin-top:8px" ${c.clearDescription?'disabled':''}>${esc(c.description)}</textarea><label class="check-label" style="margin-top:8px">${check('',c.clearDescription,'Очистить описание')}Очистить описание</label>`:''}<p class="hint" style="margin-top:16px">Неотмеченные поля сохранятся в каждом плане без изменений.</p>`;
 return html+`</div><p class="scope-note">Изменения применятся к выбранным назначенным планам. Шаблоны и будущие назначения не изменятся.</p>`;
}
function courseList(){const e=selectedElement();return e.type==='Курс'?[{id:501,name:'Охрана труда — 2025',detail:'Текущий материал',disabled:true},{id:900,name:'Охрана труда — 2027',detail:'Курс · 45 минут · опубликован'},{id:901,name:'Охрана труда для руководителей',detail:'Курс · 60 минут · опубликован'},{id:902,name:'Безопасность на рабочем месте',detail:'Курс · 30 минут · опубликован'}]:[{id:e.material,name:e.name,detail:'Текущий материал',disabled:true},{id:910,name:e.type==='Статья'?'Безопасность на производстве — новая редакция':e.type==='Опрос'?'Первые впечатления — новая версия':'Инструкция по работе с оборудованием — 2027',detail:e.type+' · опубликован'}];}
function catalogStep(){const l=courseList().filter(c=>c.name.toLowerCase().includes(state.catalogQuery.toLowerCase()));return `<label class="search">${image('magnifier-outlined.svg')}<input id="catalog-search" aria-label="Поиск материала" placeholder="Поиск по названию" value="${esc(state.catalogQuery)}"></label><div class="element-list" style="margin-top:12px">${l.length?l.map(c=>`<div class="element-option"><input type="radio" name="course" value="${c.id}" aria-label="${esc(c.name)}" ${c.disabled?'disabled':''} ${state.pendingCourse?.id===c.id?'checked':''}><span class="body"><strong>${c.name}</strong><span class="muted">${c.detail}</span></span>${action('course-info-'+c.id,'Подробнее','text-btn')}</div>`).join(''):empty('Материалы не найдены','Попробуйте другой запрос')}</div>`;}
function values(p){const c=state.config,e=selectedElement();if(c.op==='replace')return [e.name,c.replacement?.name];if(c.op==='required')return [p.required?'Обязательный':'Необязательный',c.required?'Обязательный':'Необязательный'];if(c.op==='deadline')return [formatDate(p.oldDeadline),formatDate(dateFor(p,c))];return [p.id%2?'Познакомиться с коллегами своего участка':'Познакомиться с командой',c.changeName?c.title:'Название сохраняется'];}
function applyLabel(n){return {replace:`Заменить в ${n} планах`,required:`Изменить обязательность в ${n} планах`,deadline:`Изменить срок в ${n} планах`,task:`Изменить задачи в ${n} планах`}[state.config.op];}
function detailsRows(rows,editable=false){return rows.map(r=>{const p=r.plan,[old,nw]=values(p);return `<div class="review-person">${editable?`<input type="checkbox" data-exclude="${p.id}" ${!state.excluded.has(p.id)?'checked':''} aria-label="Включить в изменение: ${p.name}">`:''}<span class="avatar">${p.initials}</span><div class="body"><strong>${p.name}</strong><p class="muted">${TEMPLATE}</p><p class="muted">${selectedElement()?.stage} / ${selectedElement()?.name}</p>${r.status==='change'||r.status==='excluded'||r.result==='success'?`<div class="change-values"><div><span>Было</span>${esc(old)}${state.config.op==='task'&&state.config.changeDescription?`<br><span>Описание</span>Текущее описание задачи сотрудника`:''}</div><div><span>Станет</span>${esc(nw)}${state.config.op==='task'&&state.config.changeDescription?`<br><span>Описание</span>${state.config.clearDescription?'Будет очищено':esc(state.config.description)}`:''}</div></div>`:''}${state.config.op==='deadline'&&state.config.dateMode!=='none'&&dateFor(p,state.config)<'2026-10-23'&&r.status==='change'?'<p class="error-text">После изменения элемент будет просрочен</p>':''}${r.reason?`<p class="muted">${reasonLabels[r.reason]||r.reason}</p>`:''}${r.message?`<p class="error-text">${r.message}</p>`:''}</div></div>`;}).join('');}
function group(title,rows,id,open=false,editable=false){return `<div class="review-group"><button class="review-head" data-toggle="${id}" aria-expanded="${open}"><span>${title} <span class="muted">${rows.length}</span></span>${chev()}</button><div class="review-body" id="${id}" ${!open?'hidden':''}>${rows.length?detailsRows(rows,editable):'<p class="hint" style="padding:16px 0">Нет планов в этой группе</p>'}</div></div>`;}
function reviewStep(){const e=selectedElement(),c=state.config,t=totals(state.preview);let beforeAfter=c.op==='replace'?`«${e.name}» → «${c.replacement.name}»`:c.op==='deadline'?c.dateMode==='days'?`${c.days} дней от начала индивидуального плана`:c.dateMode==='none'?'Без срока':formatDate(c.date):c.op==='required'?c.required?'Обязательный':'Необязательный':`${c.changeName?'Название':''}${c.changeName&&c.changeDescription?' и ':''}${c.changeDescription?'описание':''}`;
 let h=`${replacementDuplicateCount()?duplicatePanel(replacementDuplicateCount(),'edit'):''}<div class="summary"><div><strong>${opNames[c.op]}</strong><p>${esc(beforeAfter)}</p><p class="muted">${e.stage} / ${TEMPLATE}</p>${c.op==='replace'?'<p class="muted">Обязательность и сроки сохранятся</p>':''}</div>${action('change-back','Изменить настройки','text-btn')}</div><div class="counts"><div class="count positive"><span>Будут изменены</span><b>${t.change}</b></div><div class="count"><span>Изменения<br>не требуются</span><b>${t.same}</b></div><div class="count"><span>Не будут<br>изменены</span><b>${t.skip}</b></div></div>`;
 if(!t.change)h+=`<div class="notice warning">Нет планов, к которым можно применить изменение. Проверьте причины ниже или измените настройки.</div>`;
 h+=group('Будут изменены',state.preview.filter(r=>['change','excluded'].includes(r.status)),'change-list',true,true);
 h+=group('Изменения не требуются',state.preview.filter(r=>r.status==='same'),'same-list');
 const skipped=state.preview.filter(r=>r.status==='skip');h+=reasonGroups(skipped,'edit');
 if(t.excluded)h+=`<p class="hint" style="margin-top:12px">Исключены вами: ${t.excluded}. Эти планы не изменятся.</p>`;
 return h+`<p class="scope-note">Всего выбрано: ${selectionCount()}. Шаблоны и будущие назначения не изменятся.</p>`;
}
function resultHeadline(){if(state.resultMode==='add')return `Элемент добавлен в ${state.addTotal||0} планах`;const r=state.result||[],success=r.filter(r=>r.result==='success').length,error=r.some(r=>r.result==='error');return error?'Операция завершена частично':state.config.op==='replace'?`Материал заменён в ${success} планах`:`Элементы изменены в ${success} планах`;}
function resultStep(){const r=state.result||[],success=r.filter(r=>r.result==='success'),unchanged=r.filter(r=>r.result==='unchanged'),errors=r.filter(r=>r.result==='error');return `<div class="status-view"><span class="status-mark">${image('check-outlined.svg')}</span><h2>${resultHeadline()}</h2><p class="hint">Выбор планов очищен. Фильтры и группировка сохранены.</p></div><div class="counts"><div class="count positive"><span>Изменено</span><b>${success.length}</b></div><div class="count"><span>Не изменено</span><b>${unchanged.length}</b></div><div class="count ${errors.length?'negative':''}"><span>Ошибок</span><b>${errors.length}</b></div></div>${group('Изменено',success,'success-list',false)}${group('Не изменено',unchanged,'unchanged-list',false)}${group('Ошибки',errors,'error-list',errors.length>0)}`;}
function resetWith(fn){if(selectionCount()){pendingReset=fn;state.screen='reset';drawReset();}else fn();}
function drawReset(){$('#modal-root').innerHTML=`<div class="overlay"><section class="modal compact" role="dialog" aria-modal="true" aria-labelledby="reset-title"><header class="modal-head"><h2 id="reset-title">Сбросить выбор планов?</h2></header><div class="modal-content"><p>После изменения условий выбранные планы будут сброшены.</p></div><footer class="modal-foot">${action('reset-cancel','Остаться','btn ghost')}${action('reset-confirm','Сбросить и продолжить','btn primary')}</footer></section></div>`;}
function popover(anchor,html){hideBulkTip();const b=anchor.getBoundingClientRect();$('#popover-root').innerHTML=`<div class="drop">${html}</div>`;const drop=$('#popover-root .drop'),r=drop.getBoundingClientRect();drop.style.left=Math.max(12,Math.min(b.left,innerWidth-r.width-12))+'px';drop.style.top=Math.max(12,Math.min(b.bottom+8+r.height<=innerHeight-12?b.bottom+8:b.top-r.height-8,innerHeight-r.height-12))+'px';}
function start(){state.mode='edit';if(!selectionCount())return;if(selectionCount()>LIMIT){openScreen('limit');return;}if(!state.hasAccess){openScreen('denied');return;}state.element=null;state.config=initialConfig();state.excluded.clear();state.special='';state.elementQuery='';state.type='Все типы';openScreen('element');}
function checkChanges(retry=false){state.error=validate(state.config,selectedElement());if(state.error){drawModal();return;}openScreen('preview-loading');clearTimeout(loadingTimer);loadingTimer=setTimeout(()=>{if(state.screen!=='preview-loading')return;if(state.special==='preview-error'&&!retry){openScreen('preview-error');return;}state.preview=classify(chosen(),selectedElement(),state.config,state.excluded,state.special);openScreen('review');},700);}
function run(){state.resultMode='edit';if(state.screen==='running'||!totals(state.preview).change)return;openScreen('running');setTimeout(()=>{const result=execute(state.preview,state.partial);if(state.retryBase){const successfulIds=new Set(result.filter(r=>r.result==='success').map(r=>r.plan.id));state.result=state.retryBase.map(r=>successfulIds.has(r.plan.id)?{...r,result:'success',message:undefined}:r);state.retryBase=null;}else state.result=result;state.result.filter(r=>r.result==='success').forEach(r=>state.applied.set(`${r.plan.id}/${state.element}/${state.config.op}`,state.config.op==='replace'?state.config.replacement.id:JSON.stringify(state.config)));state.selected.clear();shell();openScreen('result');},1000);}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;if(!target.closest('.drop')&&!target.closest('#popover-root'))$('#popover-root').innerHTML='';if(target.dataset.toggle){const panel=document.getElementById(target.dataset.toggle);panel.hidden=!panel.hidden;target.setAttribute('aria-expanded',String(!panel.hidden));return;}if(target.dataset.page){resetWith(()=>{state.page=Number(target.dataset.page);shell();});return;}if(target.dataset.group){$('#popover-root').innerHTML='';resetWith(()=>{state.group=target.dataset.group;state.groupOpen={};state.groupPages={};state.page=1;shell();});return;}const id=target.dataset.action;
 if(id==='bulk-elements')popover(target,action('add-elements','Добавить элементы','menu-item',!state.hasAccess)+action('edit-elements','Заменить элементы','menu-item',!state.hasAccess)+action('edit-properties','Редактировать элементы','menu-item',!state.hasAccess)+action('delete-elements','Удалить элементы','menu-item',!state.hasAccess));else if(id==='bulk-participants')popover(target,action('legacy-assign','Назначить руководителя','menu-item')+action('legacy-replace','Заменить руководителя','menu-item')+action('legacy-helpers','Назначить помощников','menu-item'));else if(id==='bulk-plan')popover(target,action('legacy-deadline','Изменить дедлайн','menu-item')+action('legacy-cancel','Отменить назначение','menu-item'));else if(id==='edit-elements')start();else if(id==='clear'){state.selected.clear();shell();}else if(id==='collapse'){state.open=!state.open;shell();}else if(id==='filters'){state.filters=!state.filters;shell();}else if(id==='next'||id==='prev'){resetWith(()=>{state.page+=id==='next'?1:-1;shell();});}else if(id==='group'){popover(target,['template','department','leader','position','kind','status','none'].map(g=>`<button data-group="${g}">${{template:'По шаблону',none:'Без группировки',department:'По департаменту',leader:'По руководителю',position:'По должности',kind:'По категории',status:'По статусу'}[g]}</button>`).join(''));}else if(id==='more-actions')popover(target,['Назначить помощников','Отменить назначение'].map(t=>`<button data-action="legacy-more">${t}</button>`).join('')+`<button data-action="legacy-more">Назначить руководителя</button><button data-action="legacy-more">Заменить руководителя</button>`);else if(id?.startsWith('legacy-')||['create','reports'].includes(id))toast('Основной сценарий прототипа — «Изменить элементы».');else if(id==='columns'){popover(target,['Руководитель','Помощники','Категория плана','Дата начала','Дата окончания','Автор назначения'].map(t=>`<label class="check-label" style="padding:8px">${check('',true,t)}${t}</label>`).join(''));}else if(id==='status-filter')statusPopover(target);else if(id==='add-filter')popover(target,'<button data-action="open-status">Статус плана</button><button data-action="open-start">Дата начала</button><button data-action="open-finish">Дата окончания</button>');else if(id?.startsWith('tab-'))resetWith(()=>{state.tab=id==='tab-drafts'?'drafts':'assigned';shell();});
 else if(id==='cancel'||id==='done')closeScreen();else if(id==='element-next'){if(selectedElement()&&!selectedElement().unavailable){state.config.op=availableOps(selectedElement())[0];openScreen('change');}}else if(id==='element-back')openScreen('element');else if(id==='change-back')openScreen('change');else if(id==='catalog'){state.pendingCourse=state.config.replacement;state.catalogQuery='';openScreen('catalog');}else if(id==='catalog-cancel')openScreen('change');else if(id==='catalog-choose'){state.config.replacement=state.pendingCourse;openScreen('change');}else if(id?.startsWith('course-info-')){const c=courseList().find(c=>c.id===Number(id.slice(12)));popover(target,`<div style="padding:12px"><strong>${c.name}</strong><p class="hint" style="margin-top:8px">${c.detail}</p></div>`);}else if(id==='check'||id==='check-retry')checkChanges(id==='check-retry');else if(id==='elements-retry'){state.special='';openScreen('element');}else if(id==='apply')run();else if(id==='open-result')openScreen(state.resultMode==='add'?'add-result':'result');else if(id==='retry-errors'){const errors=state.result.filter(r=>r.result==='error');state.retryBase=state.result;state.selected=new Set(errors.map(r=>r.plan.id));state.partial=false;state.excluded.clear();state.special='';shell();checkChanges(true);}else if(id==='reset-cancel'){state.screen=null;$('#modal-root').innerHTML='';pendingReset=null;if(state.resumeOnReset){const s=state.resumeOnReset;state.resumeOnReset=null;openScreen(s);}}else if(id==='reset-confirm'){state.selected.clear();state.screen=null;$('#modal-root').innerHTML='';const fn=pendingReset;pendingReset=null;fn?.();}else if(id==='demo-launch'){state.demoOpen=!state.demoOpen;demoPanel();}
});
document.addEventListener('change',event=>{const t=event.target;if(t.matches('thead input')){const rows=selectableRows();if(rows.every(p=>state.selected.has(p.id)))rows.forEach(p=>state.selected.delete(p.id));else {const extra=rows.filter(p=>!state.selected.has(p.id));if(state.selected.size+extra.length>LIMIT){toast('Можно выбрать не более 100 планов');return;}rows.forEach(p=>state.selected.add(p.id));}shell();}else if(t.dataset.row){if(t.checked&&state.selected.size>=LIMIT){t.checked=false;toast('Можно выбрать не более 100 планов');return;}t.checked?state.selected.add(Number(t.dataset.row)):state.selected.delete(Number(t.dataset.row));shell();}else if(t.name==='element'){state.element=t.value;drawModal();}else if(t.name==='course'){state.pendingCourse=courseList().find(c=>c.id===Number(t.value));drawModal();}else if(t.id==='element-type'){state.type=t.value;drawModal();}else if(t.id==='operation'){state.config.op=t.value;state.excluded.clear();drawModal();}else if(t.name==='required'){state.config.required=t.value==='true';drawModal();}else if(t.name==='date-mode'){state.config.dateMode=t.value;drawModal();}else if(t.id==='element-date'){state.config.date=t.value;drawModal();}else if(t.id==='days'){state.config.days=t.value;drawModal();}else if(t.getAttribute('aria-label')==='Изменить название'){state.config.changeName=t.checked;drawModal();}else if(t.getAttribute('aria-label')==='Изменить описание'){state.config.changeDescription=t.checked;drawModal();}else if(t.getAttribute('aria-label')==='Очистить описание'){state.config.clearDescription=t.checked;drawModal();}else if(t.dataset.exclude){t.checked?state.excluded.delete(Number(t.dataset.exclude)):state.excluded.add(Number(t.dataset.exclude));state.preview=classify(chosen(),selectedElement(),state.config,state.excluded,state.special);drawModal();}else if(t.id==='demo-state'){loadDemo(t.value);}});
document.addEventListener('input',event=>{const t=event.target,id=t.id,pos=t.selectionStart;if(id==='table-search'){if(selectionCount()){const value=t.value;t.value=state.query;resetWith(()=>{state.query=value;state.page=1;shell();focusInput(id,pos);});}else{state.query=t.value;state.page=1;redrawInput(id,pos,shell);}}else if(id==='element-search'){state.elementQuery=t.value;redrawInput(id,pos,drawModal);}else if(id==='catalog-search'){state.catalogQuery=t.value;redrawInput(id,pos,drawModal);}else if(id==='task-title'||id==='task-description'){state.config[id==='task-title'?'title':'description']=t.value;const err=validate(state.config,selectedElement());const btn=$('[data-action="check"]');if(btn)btn.disabled=!!err;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('#popover-root').innerHTML){$('#popover-root').innerHTML='';return;}closeScreen();}if(event.key==='Tab'&&state.screen){const nodes=[...document.querySelectorAll('#modal-root button:not(:disabled),#modal-root input:not(:disabled),#modal-root select,#modal-root textarea:not(:disabled)')].filter(e=>e.getClientRects().length);if(!nodes.length){event.preventDefault();return;}const a=nodes[0],b=nodes.at(-1);if(event.shiftKey&&document.activeElement===a){event.preventDefault();b.focus();}else if(!event.shiftKey&&document.activeElement===b){event.preventDefault();a.focus();}}});
const demos=[['base','Страница назначенных планов'],['selected','Выбрана текущая страница · 20'],['element','Выбор элемента · два этапа'],['replace','Замена курса'],['required','Обязательность'],['date','Конкретная дата'],['relative','Относительный срок'],['task','Изменение задачи'],['review','Проверка · 13 / 0 / 7'],['zero','Нет подходящих планов'],['element-loading','Загрузка элементов'],['element-error','Ошибка загрузки элементов'],['empty-search','Поиск без результатов'],['no-elements','Нет элементов'],['unavailable','Нет доступных вхождений'],['preview-error','Ошибка проверки'],['stale','План изменился после проверки'],['newCourse','Новый курс уже пройден'],['limit','Ограничение · до 100 планов'],['denied','Нет прав на изменение'],['running','Применение'],['success','Успешный результат'],['partial','Частичный результат и повтор']];
function demoPanel(){$('#demo-root').innerHTML=state.demoOpen?`<div class="demo-panel"><strong>Состояния прототипа</strong><p class="small muted" style="margin-top:8px">Локальные примеры. Изменения не отправляются в LMS.</p><select id="demo-state" class="select" aria-label="Состояние прототипа"><option value="">Выберите состояние</option>${demos.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><a href="guide.html" target="_blank">Сценарий и ограничения кода ↗</a></div>`:'';}
function loadDemo(name){if(name.startsWith('v5-')||name.startsWith('v7-')||name.startsWith('v10-')){state.demoOpen=false;demoPanel();bulkFlow.demo(name);return;}state.addResult=null;state.addTotal=0;state.resultMode='edit';if(name.startsWith('add-')){loadAddDemo(name);return;}for(const p of plans)p.existingMaterials=[...p.seedMaterials];clearTimeout(loadingTimer);state.applied.clear();state.selected=new Set(plans.slice(0,20).map(p=>p.id));state.page=1;state.tab='assigned';state.query='';state.group='template';state.groupOpen={};state.groupPages={};state.statuses=[];state.startFrom='';state.startTo='';state.finishFrom='';state.finishTo='';state.mode='edit';state.open=true;state.element=elements[0].id;state.config=initialConfig();state.config.replacement={id:900,name:'Охрана труда — 2027'};state.excluded.clear();state.special='';state.partial=false;state.retryBase=null;state.result=null;state.elementQuery='';state.type='Все типы';state.hasAccess=true;state.demoOpen=false;demoPanel();
 if(name==='base'){state.selected.clear();state.screen=null;shell();drawModal();return;}if(name==='selected'){state.screen=null;shell();drawModal();return;}
 let screen=['element','element-loading','element-error','empty-search','no-elements','unavailable'].includes(name)?'element':'change';
 if(['element-loading','element-error','no-elements','unavailable','zero','stale','newCourse','preview-error'].includes(name))state.special=name;
 if(name==='element'){state.element=null;state.config.replacement=null;}if(name==='empty-search')state.elementQuery='Нет такого элемента';if(name==='unavailable')state.element=null;
 if(name==='required'){state.config.op='required';state.config.required=true;}if(name==='date')state.config.op='deadline';if(name==='relative'){state.config.op='deadline';state.config.dateMode='days';}if(name==='task'){state.element=elements[3].id;state.config.op='task';state.config.changeName=true;state.config.title='Познакомиться с командой своего участка';state.config.changeDescription=true;state.config.description='Представьтесь коллегам и обсудите рабочие задачи.';}
 if(['review','zero','stale','newCourse','running','success','partial'].includes(name)){state.preview=classify(chosen(),selectedElement(),state.config,state.excluded,state.special);screen='review';}
 if(name==='preview-error')screen='preview-error';if(name==='limit')screen='limit';if(name==='denied')screen='denied';
 if(name==='success'||name==='partial'){state.result=execute(state.preview,name==='partial');state.selected.clear();screen='result';}if(name==='running'){screen='running';}
 shell();openScreen(screen);
}

function listGroups(){return groupPlans(filtered(),state.group);}
function groupExpanded(g,i){return state.groupOpen[g.id]??i===0;}
function groupPageRows(g){return g.plans.slice(0,(state.groupPages[g.id]||1)*PAGE_SIZE);}
function tableRow(p){return `<tr class="${state.selected.has(p.id)?'selected':''}"><td><div class="employee">${check(p.id,state.selected.has(p.id),'Выбрать план: '+p.name,p.reason==='closed')}<span class="avatar">${p.initials}</span><div class="name"><strong>${p.name}</strong><span class="muted">${p.position}</span></div></div></td><td>${p.department}</td><td>Адаптация</td><td>${p.template}</td><td><span class="tag ${p.reason==='closed'?'neutral':''}">${p.status}</span></td><td><div class="progress"><div class="progress-track"><span style="width:${p.id%4*25}%"></span></div>${p.id%4*25}%</div></td><td>Елена Иванова</td><td>${formatDate(p.start)}</td><td>${formatDate(p.finish)}</td><td>Константин Белов</td></tr>`;}
function tableBody(){if(state.group==='none')return currentRows().map(tableRow).join('');return listGroups().map((g,i)=>{const expanded=groupExpanded(g,i),page=state.groupPages[g.id]||1,hasMore=page*PAGE_SIZE<g.plans.length;return `<tr class="group-row"><td colspan="10"><button class="group-button" data-expand-group="${g.id}" aria-expanded="${expanded}">${chev()}<strong>${state.group==='template'?'Шаблон ':''}«${esc(g.name)}»</strong><span class="tertiary">${g.plans.length}</span></button></td></tr>${expanded?groupPageRows(g).map(tableRow).join('')+(hasMore?`<tr><td colspan="10" class="group-pagination"><button class="group-more" data-load-group="${g.id}" aria-label="Показать ещё планы в группе ${esc(g.name)}">Показать ещё ${chev()}</button></td></tr>`:''):''}`;}).join('');}
function paginationView(total){if(state.group!=='none'||total<=PAGE_SIZE)return '';return `<nav class="pagination" aria-label="Пагинация">${action('prev',image('pagination-chevron.svg'),'page-prev',state.page===1)}${Array.from({length:Math.ceil(total/PAGE_SIZE)},(_,i)=>i+1).filter(p=>p===1||p===Math.ceil(total/PAGE_SIZE)||Math.abs(p-state.page)<2).map((p,i,a)=>`${i&&p-a[i-1]>1?'<span class="page-range">…</span>':''}<button data-page="${p}" class="${p===state.page?'active':''}" ${p===state.page?'aria-current="page"':''}>${p}</button>`).join('')}${action('next',image('pagination-chevron.svg'),'page-next',state.page>=Math.ceil(total/PAGE_SIZE))}<span class="page-size muted">По 20 на странице</span></nav>`;}
function recommended(){return state.group==='template'&&state.statuses.length===ACTIVE_STATUSES.length&&ACTIVE_STATUSES.every(s=>state.statuses.includes(s));}
function preparationNote(){return '';}
function prepareList(){const s=state.screen;if(s)state.resumeOnReset=s;resetWith(()=>{state.resumeOnReset=null;state.screen=null;$('#modal-root').innerHTML='';state.group='template';state.statuses=[...ACTIVE_STATUSES];state.filters=true;state.page=1;state.groupOpen={};state.groupPages={};shell();toast('Группировка и активные статусы включены. Выберите нужные планы.');});}
function statusCaption(){if(!state.statuses.length)return '';if(state.statuses.length===4&&ACTIVE_STATUSES.every(s=>state.statuses.includes(s)))return 'Активные · 4';return state.statuses.length===1?STATUS_LABELS[state.statuses[0]]:`Выбрано: ${state.statuses.length}`;}
function rangeCaption(from,to){return !from&&!to?'':(from?formatDate(from):'Любая дата')+' — '+(to?formatDate(to):'Любая дата');}
function filterChip(key,label,caption){return `<div class="filter-chip ${caption?'applied':''}"><button class="filter-main" data-action="open-${key}">${esc(label)}${caption?`<span>${esc(caption)}</span>`:''}</button>${caption?`<button class="filter-clear" data-action="clear-${key}" aria-label="Сбросить фильтр ${label}">${cross()}</button>`:''}</div>`;}
function changeFilters(values){$('#popover-root').innerHTML='';resetWith(()=>{Object.assign(state,values);state.page=1;state.groupOpen={};state.groupPages={};$('#popover-root').innerHTML='';shell();});}
let draftStatuses=new Set();
function statusPopover(target){draftStatuses=new Set(state.statuses.length?state.statuses:Object.keys(STATUS_LABELS));popover(target,`<div class="filter-popover"><strong>Статус плана</strong>${action('statuses-active','Выбрать активные','text-btn')}<div class="status-options">${Object.entries(STATUS_LABELS).map(([code,label])=>`<label class="check-label"><input type="checkbox" data-status-code="${code}" ${draftStatuses.has(code)?'checked':''}>${label}</label>`).join('')}</div><div class="row">${action('statuses-clear','Сбросить','btn ghost')}${action('statuses-apply','Применить','btn primary')}</div></div>`);}
function datePopover(target,kind){const start=kind==='start';popover(target,`<div class="filter-popover"><strong>${start?'Дата начала плана':'Дата окончания плана'}</strong><label class="field-label">С<input class="text-field" id="filter-date-from" aria-label="Дата с" type="date" value="${start?state.startFrom:state.finishFrom}"></label><label class="field-label">По<input class="text-field" id="filter-date-to" aria-label="Дата по" type="date" value="${start?state.startTo:state.finishTo}"></label><p class="error-text" id="range-error" role="alert"></p><div class="row">${action('clear-'+kind,'Сбросить','btn ghost')}<button class="btn primary" data-apply-range="${kind}">Применить</button></div></div>`);}
function bindPreparationTips(){for(const el of document.querySelectorAll('[data-action="edit-elements"],[data-action="add-elements"]')){el.dataset.tip='Перед изменением элементов сгруппируйте планы «По шаблону» и выберите активные планы в фильтре «Статус». Так проще выбрать нужные элементы.';el.setAttribute('aria-describedby','bulk-tip');}}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;const id=target.dataset.action;if(id==='prepare-list')prepareList();else if(id==='open-status')statusPopover(target);else if(id==='open-start'||id==='open-finish')datePopover(target,id.slice(5));else if(id==='clear-status'||id==='statuses-clear')changeFilters({statuses:[]});else if(id==='clear-start')changeFilters({startFrom:'',startTo:''});else if(id==='clear-finish')changeFilters({finishFrom:'',finishTo:''});else if(id==='statuses-active'){draftStatuses=new Set(ACTIVE_STATUSES);for(const input of document.querySelectorAll('[data-status-code]'))input.checked=draftStatuses.has(input.dataset.statusCode);}else if(id==='statuses-apply')changeFilters({statuses:draftStatuses.size===7?[]:[...draftStatuses]});else if(target.dataset.applyRange){const from=$('#filter-date-from').value,to=$('#filter-date-to').value;if(!validRange(from,to)){$('#range-error').textContent='Дата «С» не может быть позже даты «По»';return;}changeFilters(target.dataset.applyRange==='start'?{startFrom:from,startTo:to}:{finishFrom:from,finishTo:to});}else if(target.dataset.expandGroup){const group=listGroups().find(g=>g.id===target.dataset.expandGroup);state.groupOpen[group.id]=!groupExpanded(group,listGroups().findIndex(g=>g.id===group.id));shell();}else if(target.dataset.groupPage){const key=target.dataset.groupPage,offset=Number(target.dataset.offset);resetWith(()=>{state.groupPages[key]=(state.groupPages[key]||1)+offset;shell();});}});
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.statusCode)t.checked?draftStatuses.add(t.dataset.statusCode):draftStatuses.delete(t.dataset.statusCode);});
function showBulkTip(el){if(el.disabled||document.querySelector('#modal-root [role="dialog"]'))return;let tip=$('#bulk-tip');if(!tip){tip=document.createElement('div');tip.id='bulk-tip';tip.role='tooltip';tip.className='bulk-tooltip';document.body.append(tip);}tip.textContent=el.dataset.tip;tip.hidden=false;const r=el.getBoundingClientRect(),drop=el.closest('.drop')?.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let left,top;if(drop&&(drop.right+12+w<=innerWidth-12||drop.left-12-w>=12)){left=drop.right+12+w<=innerWidth-12?drop.right+12:drop.left-12-w;top=r.top;}else{left=r.left;top=r.top-h-12;}tip.style.left=Math.max(12,Math.min(left,innerWidth-w-12))+'px';tip.style.top=Math.max(12,Math.min(top,innerHeight-h-12))+'px';}
function hideBulkTip(){const tip=$('#bulk-tip');if(tip)tip.hidden=true;}
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-tip]');if(el&&!el.contains(e.relatedTarget))showBulkTip(el);});
document.addEventListener('pointerout',e=>{const el=e.target.closest('[data-tip]');if(el&&!el.contains(e.relatedTarget))hideBulkTip();});
document.addEventListener('focusin',e=>{const el=e.target.closest('[data-tip]');if(el)showBulkTip(el);});
document.addEventListener('focusout',hideBulkTip);document.addEventListener('click',hideBulkTip,true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideBulkTip();});
document.addEventListener('scroll',hideBulkTip,true);window.addEventListener('resize',hideBulkTip);

function startAdd(){if(!selectionCount())return;if(selectionCount()>LIMIT){openScreen('limit');return;}state.mode='add';state.addStage=null;state.addConfig=initialAddConfig();state.excluded.clear();openScreen('add-stage');}
function selectedStage(){if(state.screen==='add-result'&&state.lastAddStage)return state.lastAddStage;return STAGES.find(s=>s.id===state.addStage);}
function stageRange(stage){const rows=chosen().map(id=>plans.find(p=>p.id===id)).filter(p=>p.templateId===stage.templateId),dates=rows.map(p=>stageDates(p,stage));if(!dates.length)return 'Этап не найден';const starts=dates.map(d=>d.start).sort(),finishes=dates.map(d=>d.finish).sort();return `С ${formatDate(starts[0])}${starts[0]!==starts.at(-1)?'–'+formatDate(starts.at(-1)):''} · по ${formatDate(finishes[0])}${finishes[0]!==finishes.at(-1)?'–'+formatDate(finishes.at(-1)):''}`;}
function elementTiming(el){const stage=stageForElement(el),rows=chosen().map(id=>plans.find(p=>p.id===id)).filter(p=>p.templateId===stage.templateId);const days=el.id.includes('/s3/')?37:el.id.includes('/s4/')?75:el.id.includes('/s2/')?25:5;const deadlines=rows.map(p=>{const d=new Date(p.start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}).sort();return `<dl class="element-facts"><div><dt>Этап</dt><dd><strong>${el.stage}</strong> · ${stage.from+1}–${stage.to}-й день</dd></div><div><dt>Срок элемента</dt><dd>${deadlines.length?'До '+formatDate(deadlines[0])+(deadlines[0]!==deadlines.at(-1)?'–'+formatDate(deadlines.at(-1)):''):'Не указан'}${deadlines[0]!==deadlines.at(-1)?'<span class="muted"> · зависит от начала плана</span>':''}</dd></div></dl>`;}
function addMaterials(){const c=state.addConfig;return c.type==='Курс'?[{id:900,name:'Охрана труда — 2027',detail:'Курс · опубликован'},{id:901,name:'Охрана труда для руководителей',detail:'Курс · уже есть в части планов'},{id:902,name:'Безопасность на рабочем месте',detail:'Курс · опубликован'},{id:501,name:'Охрана труда — 2025',detail:'Курс · может встречаться в маршруте'}]:c.type==='Статья'?[{id:920,name:'Памятка нового сотрудника',detail:'Статья · опубликована'}]:c.type==='Файл'?[{id:930,name:'Инструкция по работе с оборудованием.pdf',detail:'Файл · PDF'}]:[{id:940,name:'Обратная связь после первой недели',detail:'Опрос · опубликован'}];}
function addStageStep(){const options=STAGES.filter(s=>chosen().some(id=>plans.find(p=>p.id===id).templateId===s.templateId));return `<p class="context-note">Выбрано планов: ${selectionCount()}</p>${preparationNote(true)}<p class="hint" style="margin:16px 0 8px">Выберите конкретный этап. Одинаковые названия в разных шаблонах не объединяются.</p><div class="element-list">${options.map(s=>{const count=chosen().filter(id=>plans.find(p=>p.id===id).templateId===s.templateId).length;return `<label class="element-option"><input type="radio" name="add-stage" value="${s.id}" ${s.id===state.addStage?'checked':''}><span class="body"><strong>${s.name}</strong><span class="meta">${plans.find(p=>p.templateId===s.templateId).template} · маршрут сотрудника</span><span class="availability">Найден в ${count} планах из ${selectionCount()}</span><span class="stage-dates">${stageRange(s)}</span></span></label>`;}).join('')}</div>`;}
function addConfigStep(){const c=state.addConfig,s=selectedStage();return `<div class="chosen-element"><div class="body"><strong>Этап «${s.name}»</strong><p class="muted">${plans.find(p=>p.templateId===s.templateId).template}</p><p class="small muted">${stageRange(s)}</p></div>${action('add-stage-back','Другой этап','text-btn')}</div><div class="form-field"><label class="field-label" for="add-type">Тип нового элемента</label><select class="select" id="add-type">${['Курс','Статья','Файл','Опрос','Задача'].map(t=>`<option ${c.type===t?'selected':''}>${t}</option>`).join('')}</select></div>${c.type==='Задача'?`<div class="form-field"><label class="field-label" for="add-title">Название задачи</label><input class="text-field" id="add-title" value="${esc(c.title)}"></div><div class="form-field"><label class="field-label" for="add-description">Описание</label><textarea id="add-description" rows="3">${esc(c.description)}</textarea></div>`:`<div class="form-field"><span class="field-label">Новый материал</span>${c.material?`<div class="chosen-element"><div class="body"><strong>${esc(c.material.name)}</strong><span class="muted">${c.type}</span></div>${action('add-catalog','Изменить','text-btn')}</div>`:action('add-catalog','Выбрать материал','btn')}</div>`}<div class="form-field"><label class="check-label"><input type="checkbox" id="add-required" ${c.required?'checked':''} ${s.required?'disabled':''}>Обязательный элемент</label>${s.required?'<p class="hint">Этап обязательный — новый элемент тоже будет обязательным.</p>':''}</div><div class="form-field"><span class="field-label">Срок нового элемента</span>${[['days','Дней от начала индивидуального плана'],['date','Конкретная дата'],['none','Без срока']].map(([v,t])=>`<label class="radio-line"><input type="radio" name="add-date-mode" value="${v}" ${c.dateMode===v?'checked':''}>${t}</label>`).join('')}<div style="margin:8px 0 0 28px">${c.dateMode==='days'?`<label class="row"><input class="text-field" style="width:100px" type="number" id="add-days" min="0" value="${c.days}" aria-label="Дней на выполнение нового элемента">дней от начала плана</label>`:c.dateMode==='date'?`<input class="text-field" type="date" id="add-date" value="${c.date}" aria-label="Срок нового элемента">`:''}</div><p class="hint" style="margin-top:12px">Проверим срок отдельно для каждого плана: он должен попадать в период выбранного этапа и не выходить за окончание плана.</p></div><p class="scope-note">Элемент добавится в конец выбранного этапа. Шаблон и будущие назначения не изменятся.</p>`;}
function duplicatePanel(count,mode){const c=mode==='add'?state.addConfig:state.config;return `<div class="notice warning duplicate-notice"><strong>Материал уже есть в ${count} ${count===1?'плане':'планах'}</strong><p>Добавить повторное вхождение в маршрут? Существующие элементы не удаляются.</p><label class="radio-line"><input type="radio" name="duplicate-decision" value="skip" ${c.duplicateDecision==='skip'?'checked':''}>Пропустить эти планы</label><label class="radio-line"><input type="radio" name="duplicate-decision" value="allow" ${c.duplicateDecision==='allow'?'checked':''}>${mode==='add'?'Добавить повторно':'Всё равно заменить выбранное вхождение'}</label><p class="small">Повторная строка не означает новое прохождение курса. Сброс результатов не предлагается.</p>${!c.duplicateDecision?'<p class="error-text">Выберите действие для найденных дублей</p>':''}</div>`;}
function addPeople(rows){return rows.map(r=>`<div class="review-person"><span class="avatar">${r.plan.initials}</span><div class="body"><strong>${r.plan.name}</strong><p class="muted">${r.plan.template} / ${selectedStage().name}</p><div class="change-values"><div><span>Период этапа</span>${formatDate(r.stageDates.start)}–${formatDate(r.stageDates.finish)}<span>Окончание плана</span>${formatDate(r.plan.finish)}</div><div><span>Срок нового элемента</span>${r.deadline?formatDate(r.deadline):'Без срока'}${r.duplicate?'<span>Материал уже есть в маршруте</span>':''}</div></div>${r.reason?`<p class="error-text">${reasonLabels[r.reason]||r.reason}</p>`:''}</div></div>`).join('');}
function addReviewStep(){const c=state.addConfig,s=selectedStage(),rows=state.addPreview,t=totals(rows),dups=rows.filter(r=>r.duplicate&&!['closed','stageMissing','planDate','date','beforeStage'].includes(r.reason)).length;return `<div class="summary"><div><strong>Добавить ${c.type.toLowerCase()} «${esc(c.material?.name||c.title)}»</strong><p>В конец этапа «${s.name}»</p><p class="muted">${c.required?'Обязательный':'Необязательный'} · ${c.dateMode==='days'?c.days+' дней от начала плана':c.dateMode==='date'?formatDate(c.date):'Без срока'}</p></div>${action('add-config-back','Изменить','text-btn')}</div>${dups?duplicatePanel(dups,'add'):''}${rows.some(r=>r.deadline&&r.deadline<'2026-10-23'&&r.status==='change')?'<div class="notice warning" style="margin-bottom:16px">В части планов новый срок уже прошёл. После добавления элемент будет просрочен — конкретные даты показаны в списке.</div>':''}<div class="counts"><div class="count positive"><span>Будут дополнены</span><b>${t.change}</b></div><div class="count"><span>Не будут<br>изменены</span><b>${t.skip}</b></div><div class="count"><span>Всего выбрано</span><b>${selectionCount()}</b></div></div>${!t.change?'<div class="notice warning">Нет подходящих планов. Проверьте причины и скорректируйте срок или этап.</div>':''}<div class="review-group"><button class="review-head" data-toggle="add-ready" aria-expanded="false">Будут дополнены · ${t.change}${chev()}</button><div class="review-body" id="add-ready" hidden>${addPeople(rows.filter(r=>r.status==='change'))}</div></div>${reasonGroups(rows.filter(r=>r.status==='skip'),'add')}<p class="scope-note">Назначенные планы изменятся только после нажатия «Добавить». Совпадение названий этапов не используется для автоматического сопоставления.</p>`;}
function reasonGroups(rows,mode='edit'){const keys=[...new Set(rows.map(r=>r.reason))];return `<div class="review-group"><button class="review-head" data-toggle="${mode}-skips" aria-expanded="true"><span>Не будут изменены · ${rows.length}</span>${chev()}</button><div class="review-body" id="${mode}-skips">${keys.length?keys.map((key,i)=>{const list=rows.filter(r=>r.reason===key);return `<button class="reason-heading" data-toggle="${mode}-reason-${i}" aria-expanded="false"><span>${reasonLabels[key]||key} <b>${list.length}</b></span>${chev()}</button><div id="${mode}-reason-${i}" hidden>${mode==='add'?addPeople(list):detailsRows(list)}</div>`;}).join(''):'<p class="hint" style="padding:16px 0">Все планы подходят</p>'}</div></div>`;}
function refreshAddPreview(){state.addPreview=addRows(chosen(),selectedStage(),state.addConfig);}
function drawAddModal(){const c=state.addConfig,s=selectedStage();let title='Добавить элементы',description='',body='',footer='',at=1;
 if(state.screen==='add-stage'){description='Выберите этап для нового элемента в назначенных планах';body=addStageStep();footer=action('cancel','Отменить','btn ghost')+action('add-next','Далее','btn primary',!s);}
 if(state.screen==='add-config'){at=2;body=addConfigStep();footer=action('add-stage-back','Назад','btn ghost left')+action('add-check','Проверить добавление','btn primary',!!validateAdd(c));}
 if(state.screen==='add-catalog'){at=2;title='Выбрать материал';body=`<label class="search">${image('magnifier-outlined.svg')}<input id="add-catalog-search" value="${esc(state.addCatalogQuery||'')}" placeholder="Поиск материала" aria-label="Поиск нового материала"></label><div class="element-list">${addMaterials().filter(m=>m.name.toLowerCase().includes((state.addCatalogQuery||'').toLowerCase())).map(m=>`<label class="element-option"><input type="radio" name="add-material" value="${m.id}" ${state.addPending?.id===m.id?'checked':''}><span class="body"><strong>${m.name}</strong><span class="muted">${m.detail}</span></span></label>`).join('')||empty('Материалы не найдены')}</div>`;footer=action('add-config-back','Назад','btn ghost left')+action('add-choose','Выбрать','btn primary',!state.addPending);}
 if(state.screen==='add-loading'){at=3;body='<div class="empty"><span class="loader"></span><h3>Проверяем этапы, сроки и дубли…</h3></div>';footer=action('add-config-back','Назад','btn ghost');}
 if(state.screen==='add-review'){at=3;title='Проверьте добавление';body=addReviewStep();const pending=state.addPreview.some(r=>r.duplicate&&r.reason==='duplicate')&&!c.duplicateDecision;footer=action('add-config-back','Назад','btn ghost left')+action('add-apply',`Добавить в ${totals(state.addPreview).change} планах`,'btn primary',!totals(state.addPreview).change||pending);}
 if(state.screen==='add-running'){at=3;title='Добавляем элементы';body=`<div class="empty"><span class="loader"></span><h3>Добавляем элемент в ${totals(state.addPreview).change} планах…</h3><p>Дождитесь результата</p></div>`;footer=action('none','Выполняем…','btn primary',true);}
 if(state.screen==='add-result'){at=3;title='Результат добавления';const success=state.addResult.filter(r=>r.status==='change'),skip=state.addResult.filter(r=>r.status==='skip');body=`<div class="status-view"><span class="status-mark">${image('check-outlined.svg')}</span><h2>Элемент добавлен в ${success.length} планах</h2><p class="hint">${skip.length} планов не изменены. Выбор очищен, фильтры и группировка сохранены.</p></div>${reasonGroups(skip,'add')}`;footer=action('done','Готово','btn primary');}
 $('#modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${title}</h2>${state.screen!=='add-running'?`<button class="icon-btn" data-action="cancel" aria-label="Закрыть">${cross()}</button>`:''}${description?`<p>${description}</p>`:''}${!['add-result','add-running'].includes(state.screen)?`<div class="steps">${['Этап','Новый элемент','Проверка'].map((t,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${at===i+1?'current':''}"><b>${i+1}</b>${t}</span>`).join('')}</div>`:''}</header><div class="modal-content">${body}</div><footer class="modal-foot">${footer}</footer></section></div>`;if(state.screen==='add-running'){const dialog=$('#modal-root [role=dialog]');dialog.tabIndex=-1;dialog.focus();}else $('#modal-root .modal-head button')?.focus();}
document.addEventListener('click',event=>{const t=event.target.closest('button');if(!t||t.disabled)return;const id=t.dataset.action;if(id==='add-elements')startAdd();else if(id==='add-next')openScreen('add-config');else if(id==='add-stage-back')openScreen('add-stage');else if(id==='add-config-back')openScreen('add-config');else if(id==='add-catalog'){state.addCatalogQuery='';state.addPending=state.addConfig.material;openScreen('add-catalog');}else if(id==='add-choose'){state.addConfig.material=state.addPending;state.addConfig.duplicateDecision=null;openScreen('add-config');}else if(id==='add-check'){openScreen('add-loading');setTimeout(()=>{if(state.screen!=='add-loading')return;refreshAddPreview();openScreen('add-review');},600);}else if(id==='add-apply'){openScreen('add-running');setTimeout(()=>{state.lastAddStage=selectedStage();state.resultMode='add';state.addResult=state.addPreview;for(const r of state.addResult.filter(r=>r.status==='change')){if(state.addConfig.material&&!r.plan.existingMaterials.includes(state.addConfig.material.id))r.plan.existingMaterials.push(state.addConfig.material.id);}state.addTotal=state.addResult.filter(r=>r.status==='change').length;state.selected.clear();shell();openScreen('add-result');},900);}});
document.addEventListener('change',e=>{const t=e.target,c=state.addConfig;if(t.name==='add-stage'){state.addStage=t.value;if(selectedStage().required)c.required=true;drawAddModal();}else if(t.id==='add-type'){c.type=t.value;c.material=null;drawAddModal();}else if(t.name==='add-material'){state.addPending=addMaterials().find(m=>m.id===Number(t.value));drawAddModal();}else if(t.id==='add-required'){c.required=t.checked;}else if(t.name==='add-date-mode'){c.dateMode=t.value;drawAddModal();}else if(t.id==='add-days'||t.id==='add-date'){c[t.id==='add-days'?'days':'date']=t.value;const b=$('[data-action="add-check"]');if(b)b.disabled=!!validateAdd(c);}else if(t.name==='duplicate-decision'){if(state.mode==='add'){c.duplicateDecision=t.value;refreshAddPreview();drawAddModal();}else{state.config.duplicateDecision=t.value;state.preview=classify(chosen(),selectedElement(),state.config,state.excluded,state.special);drawModal();}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='add-title'||t.id==='add-description'){state.addConfig[t.id==='add-title'?'title':'description']=t.value;const b=$('[data-action="add-check"]');if(b)b.disabled=!!validateAdd(state.addConfig);}else if(t.id==='add-catalog-search'){const pos=t.selectionStart;state.addCatalogQuery=t.value;drawAddModal();focusInput(t.id,pos);}});

Object.assign(reasonLabels,{duplicate:'Материал уже есть в плане',stageMissing:'Выбранный этап не найден в этом шаблоне',planDate:'Срок элемента выходит за окончание плана',beforeStage:'Срок элемента раньше начала этапа'});
function replacementDuplicateCount(){return state.config.op==='replace'&&state.config.replacement?classifyModel(chosen(),selectedElement(),state.config,state.excluded,state.special).filter(r=>r.status==='change'&&r.plan.existingMaterials.includes(state.config.replacement.id)).length:0;}

function loadAddDemo(name){state.result=null;state.addResult=null;state.addTotal=0;state.resultMode='edit';clearTimeout(loadingTimer);for(const p of plans)p.existingMaterials=[...p.seedMaterials];state.selected=new Set(plans.slice(0,20).map(p=>p.id));state.page=1;state.tab='assigned';state.group='template';state.groupOpen={};state.groupPages={};state.statuses=[...ACTIVE_STATUSES];state.query='';state.startFrom='';state.startTo='';state.finishFrom='';state.finishTo='';state.mode='add';state.addConfig=initialAddConfig();state.addStage=name==='add-stage'?null:'t1/s1';state.addConfig.material={id:900,name:'Охрана труда — 2027'};state.demoOpen=false;demoPanel();if(name==='add-duplicates')state.addConfig.material={id:901,name:'Охрана труда для руководителей'};if(name==='add-invalid-date'){state.addConfig.dateMode='date';state.addConfig.date='2027-03-01';}let screen=name==='add-stage'?'add-stage':name==='add-config'?'add-config':'add-review';if(screen==='add-review')refreshAddPreview();shell();openScreen(screen);}
demos.push(['add-stage','Добавить элемент · выбор этапа'],['add-config','Добавить элемент · материал и срок'],['add-review','Проверка добавления'],['add-duplicates','Материал уже есть · требуется решение'],['add-invalid-date','Срок за границами этапа и плана']);

const bulkFlow=createBulkWorkflow({plans,getSelected:chosen,onCommitted:summary=>{state.workflowSummary=summary;state.result=null;state.addResult=null;state.selected.clear();state.screen=null;shell();},prepareDemo:()=>{state.screen=null;state.workflowSummary=null;state.result=null;state.addResult=null;state.selected=new Set(plans.slice(0,20).map(p=>p.id));state.page=1;state.query='';state.group='none';state.statuses=[];state.startFrom='';state.startTo='';state.finishFrom='';state.finishTo='';shell();}});
demos.splice(0,demos.length,['base','Страница назначенных планов'],['selected','Выбрано 20 планов'],...FLOW_DEMOS);
shell();const initialState=new URLSearchParams(location.search).get('state');if(initialState&&demos.some(([v])=>v===initialState))loadDemo(initialState);

document.addEventListener('click',e=>{if(['running','add-running'].includes(state.screen)&&!e.target.closest('#demo-root,#demo-launch')){e.preventDefault();e.stopImmediatePropagation();}},true);

document.addEventListener('click',e=>{const btn=e.target.closest('[data-load-group]');if(!btn)return;const scroll=$('.table-scroll'),top=scroll.scrollTop,left=scroll.scrollLeft;const id=btn.dataset.loadGroup;state.groupPages[id]=(state.groupPages[id]||1)+1;shell();$('.table-scroll').scrollTop=top;$('.table-scroll').scrollLeft=left;});
